<?php
$competency_list = function ($competencies) {
    $items = array_filter(array_map('trim', preg_split('/\r\n|\r|\n/', (string) $competencies)));
    if (empty($items)) {
        return '—';
    }
    $html = '<ul class="least-learned-list">';
    foreach ($items as $item) {
        $html .= '<li>' . html_escape($item) . '</li>';
    }
    return $html . '</ul>';
};
?>
