ull ? number_format((float) $row->class_proficiency_level, 2) . '%' : '—'; ?></td><td><?= isset($row->proficiency_level) && $row->proficiency_level !== null ? html_escape($row->proficiency_level) : '—'; ?></td><td class="wide"><?= $competency_list($row->least_learned_competency); ?></td><td><?= number_format((float) $row->percent_not_meeting, 1); ?>%</td><td><?= (int) $row->learners_assessed; ?></td><td><?= (int) $row->learners_with_gap; ?></td><td class="wide"><?= nl2br(html_escape($row->learning_difficulty)); ?></td><td class="wide"><?= nl2br(html_escape($row->possible_causes)); ?></td><td class="wide"><?= nl2br(html_escape($row->intervention_action)); ?></td><td><span class="badge-status"><?= html_escape($row->intervention_status ?: 'Not set'); ?></span></td><td class="wide"><?= nl2br(html_escape($row->remarks)); ?></td><?php if ($is_school): ?><td><a class="btn btn-sm btn-outline-primary" href="<?= base_url('Pages/learning_gap_entry?edit=' . (int) $row->id); ?>" title="Edit record"><i class="mdi mdi-pencil"></i></a> <a class="btn btn-sm btn-outline-danger" onclick="return confirm('Remove this record?');" href="<?= base_url('Pages/learning_gap_delete/' . (int) $row->id); ?>" title="Delete record"><i class="mdi mdi-delete-outline"></i></a></td><?php endif; ?></tr><?php endforeach; endif; ?></tbody></table></div></div>
